const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright (c) 2015 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.timeline-status-dialog {\n  display: flex;\n  flex-direction: column;\n  padding: 16px 16px 12px;\n  align-self: center;\n  background-color: var(--color-background);\n  box-shadow: var(--drop-shadow);\n}\n\n.status-dialog-line {\n  margin: 2px;\n  height: 14px;\n  min-height: auto;\n  display: flex;\n  align-items: baseline;\n}\n\n.status-dialog-line .label {\n  display: inline-block;\n  width: 80px;\n  text-align: right;\n  color: var(--color-text-primary);\n  margin-right: 10px;\n}\n\n.timeline-status-dialog .progress .indicator-container {\n  display: inline-block;\n  width: 200px;\n  height: 8px;\n  background-color: var(--color-background-elevation-2);\n}\n\n.timeline-status-dialog .progress .indicator {\n  background-color: var(--color-primary-variant);\n  height: 100%;\n  width: 0;\n  margin: 0;\n}\n\n.timeline-status-dialog .stop-button {\n  margin-top: 8px;\n  height: 100%;\n  align-self: flex-end;\n}\n\n.timeline-status-dialog .stop-button button {\n  min-width: 80px;\n}\n\n.timeline-status-dialog.small-dialog {\n  width: inherit;\n  justify-content: center;\n}\n\n.small-dialog > .stop-button {\n  align-self: center;\n  margin-top: 20px;\n  height: initial;\n}\n\n@media (forced-colors: active) {\n  .timeline-status-dialog {\n    border: 1px solid canvastext;\n  }\n\n  .timeline-status-dialog .progress .indicator-container {\n    border: 1px solid ButtonText;\n    background-color: ButtonFace;\n  }\n\n  .timeline-status-dialog .progress .indicator {\n    forced-color-adjust: none;\n    background-color: ButtonText;\n  }\n}\n\n/*# sourceURL=timelineStatusDialog.css */\n");export default styles;